    /** The only real ores dripstone, a cave calcite, keeps. */
    private static final Set<String> DRIPSTONE_KEEPS = Set.of("antimony", "biggerreactors_uranium", "copper", "dense_fluorite", "dense_lead", "dense_uranium", "embers_lead", "expandeddelight_salt", "galena", "ie_aluminum", "ie_lead", "ie_uranium", "iron", "lead", "manganese", "mek_fluorite", "mek_lead", "mek_uranium", "mi_bauxite", "mi_lead", "oreganized_lead", "salt", "superbwarfare_galena", "tankdefenses_aluminum", "techreborn_bauxite", "techreborn_lead", "techreborn_uranium", "uraninite", "uraninite_dense", "uraninite_poor", "uranium", "yellorite", "zinc");

    /** Cobblemon's evolution stones: judged in dripstone by their lore (ROCK), not by DRIPSTONE_KEEPS. */
    private static final Set<String> COBBLEMON = Set.of("dawn_stone", "dusk_stone", "fire_stone", "ice_stone", "leaf_stone", "moon_stone", "shiny_stone", "sun_stone", "thunder_stone", "water_stone");

    /** The game's own ores: their refusals in the game's own rock are the option's, never fixed. */
    private static final Set<String> VANILLA_ORES = Set.of("coal", "copper", "diamond", "emerald", "gold", "iron", "lapis", "nether_gold", "quartz", "redstone");

    private static final Set<String> GAME_ROCK = Set.of("andesite", "basalt", "blackstone", "diorite", "dripstone", "granite", "tuff");

    /** The End's crystalline stones: they keep gems, and fiction, only. */
    private static final Set<String> END_GEM_STONES = Set.of("mythicupgrades_jade_schist");

    private static final Set<String> GEMS = Set.of("alexandrite", "amethyst", "ametrine", "ammolite", "aquamarine", "black_diamond", "black_opal", "carnelian", "citrine", "diamond", "emerald", "epicpaladins_jade", "garnet", "heliodor", "iceandfire_sapphire", "iolite", "jade", "kyanite", "lapis", "moldavite", "opal", "pearl", "peridot", "quartz", "rose_quartz", "ruby", "sapphire", "silents_aquamarine", "silents_citrine", "silents_peridot", "silents_ruby", "silents_sapphire", "silents_topaz", "tanzanite", "techreborn_ruby", "techreborn_sapphire", "topaz", "turquoise", "white_diamond");

    /** Stones other mods place that are judged as one of the game's rocks (gneiss as granite). */
    private static final Map<String, String> ROCK_AS = Map.ofEntries(
            Map.entry("embellishcraft_gneiss", "granite"),
            Map.entry("embellishcraft_larvikite", "diorite"));

    private static boolean rockRefuses(String host, String ore) {
        if ("dripstone".equals(host) && !FICTION.contains(ore)) {
            return !DRIPSTONE_KEEPS.contains(ore);
        }
        return ROCK.getOrDefault(ore, Set.of()).contains(host);
    }

    /** Whether this ore never forms in this host, for good: no variant, worldgen makes it the stone. */
    public static boolean fixed(String host, String ore) {
        if (GAME_ROCK.contains(host)) {
            return !VANILLA_ORES.contains(ore) && rockRefuses(host, ore);
        }
        if (STRICT.getOrDefault(ore, Set.of()).contains(host)) {
            return true;
        }
        if (END_GEM_STONES.contains(host)) {
            return !GEMS.contains(ore) && !FICTION.contains(ore);
        }
        if (ROCK_AS.containsKey(host)) {
            return rockRefuses(ROCK_AS.get(host), ore);
        }
        final String keep = LORE.get(host);
        return keep != null && !keep.equals(ore) && !FICTION.contains(ore);
    }

    /** Whether the geology option, when on, refuses this VANILLA ore in this rock of the game's own. */
    public static boolean optional(String host, String ore) {
        return GAME_ROCK.contains(host) && VANILLA_ORES.contains(ore) && rockRefuses(host, ore);
    }
